    54→  @Override
    55→  public <T> T getBitmapResult(BitmapIndexSelector selector, BitmapResultFactory<T> bitmapResultFactory)
    56→  {
    57→    final Context cx = Context.enter();
    58→    try {
    59→      return Filters.matchPredicate(dimension, selector, bitmapResultFactory, makeStringPredicate(cx));
    60→    }
    61→    finally {
